  /*
   * @param column
   * @return Store that goes with the family on passed <code>column</code>.
   * TODO: Make this lookup faster.
   */
  protected HStore getStore(final byte [] column) {
    return this.stores.get(HStoreKey.getFamilyMapKey(column)); 
  }

