  /**
   * Method to transform a set of column families in byte[] format into a
   * signature for printing out in metrics
   *
   * @param families
   *          the ordered set of column families
   * @return a string to print out in metrics
   */
  public static String createMutationSignature(Set<byte[]> families) {
    int limit = families.size();
    if (1 == limit) {
      return SchemaMetrics.CF_PREFIX +
          Bytes.toString(families.iterator().next());
    }

    List<byte[]> sortedFamilies = new ArrayList<byte[]>(families);
    Collections.sort(sortedFamilies, Bytes.BYTES_COMPARATOR);

    StringBuilder sb = new StringBuilder(SchemaMetrics.CF_PREFIX);

    int MAX_SIZE = 256;
    for (byte[] family : sortedFamilies) {
      if (sb.length() > MAX_SIZE) {
        sb.append("__more");
        break;
      }

      --limit;
      sb.append(Bytes.toString(family));
      if (0 != limit) {
        sb.append("~");
      }
    }

    return sb.toString();
  }

  /**
   * Method to transform a single column family in byte[] format into a
   * signature for printing out in metrics. Used as overloading so as to not
   * create an extra Set. Could have gone further and imposed restriction on the
   * Set version to be used for length > 1, but that puts strain on method user.
   *
   * @param family
   *          the family to convert
   * @return the string to print out in metrics
   */
  public static String createMutationSignature(byte[] family) {
    return SchemaMetrics.CF_PREFIX + Bytes.toString(family);
  }

  public static void incrNumericMetric(String key, long amount) {
    AtomicLong oldVal = numericMetrics.get(key);
    if (oldVal == null) {
      oldVal = numericMetrics.putIfAbsent(key, new AtomicLong(amount));
      if (oldVal == null)
        return;
    }
    oldVal.addAndGet(amount);
  }

  public static void setNumericMetric(String key, long amount) {
    numericMetrics.put(key, new AtomicLong(amount));
  }

  public static void incrNumericPersistentMetric(String key, long amount) {
    AtomicLong oldVal = numericPersistentMetrics.get(key);
    if (oldVal == null) {
      oldVal = numericPersistentMetrics.putIfAbsent(key, new AtomicLong(amount));
      if (oldVal == null)
        return;
    }
    oldVal.addAndGet(amount);
  }

  public static void incrTimeVaryingMetric(String key, long amount) {
    Pair<AtomicLong, AtomicInteger> oldVal = timeVaryingMetrics.get(key);
    if (oldVal == null) {
      oldVal = timeVaryingMetrics.putIfAbsent(key,
           new Pair<AtomicLong, AtomicInteger>(new AtomicLong(amount),
                                              new AtomicInteger(1)));
      if (oldVal == null)
        return;
    }
    oldVal.getFirst().addAndGet(amount);  // total time
    oldVal.getSecond().incrementAndGet(); // increment ops by 1
  }

  public static long getNumericMetric(String key) {
    AtomicLong m = numericMetrics.get(key);
    if (m == null)
      return 0;
    return m.get();
  }

  public static Pair<Long, Integer> getTimeVaryingMetric(String key) {
    Pair<AtomicLong, AtomicInteger> pair = timeVaryingMetrics.get(key);
    if (pair == null) {
      return new Pair<Long, Integer>(0L, 0);
    }

    return new Pair<Long, Integer>(pair.getFirst().get(),
        pair.getSecond().get());
  }

  static long getNumericPersistentMetric(String key) {
    AtomicLong m = numericPersistentMetrics.get(key);
    if (m == null)
      return 0;
    return m.get();
  }

