            // check 4.3.1.c1 error: fBase.length & (maxLength | minLength)
            if ( ((fBase.fFacetsDefined & FACET_LENGTH ) != 0 ) ) {
                if ((fFacetsDefined & FACET_MAXLENGTH ) != 0 ||
                    (fFacetsDefined & FACET_MINLENGTH ) != 0 ) {
