        try {
            if (htmlMode) {
                pwQuery.println("</BODY></HTML>");
                pwQuery.flush();
            }
        } finally {
            try {
                pwQuery.close();
            } finally {
                pwQuery = null; // Encourage GC of buffers
            }
        }
    }

