            row[increment] = String.valueOf(sequence.getIncrement());
            row[cycle_option]               = sequence.isCycle() ? "YES"
                                                                 : "NO";
            row[declared_data_type]         = row[data_type];
            row[declared_numeric_precision] = row[numeric_precision];
            row[declared_numeric_scale]     = row[declared_numeric_scale];
            row[start_with] = String.valueOf(sequence.getStartValue());
            row[next_value]                 = String.valueOf(sequence.peek());

            t.insertSys(session, store, row);
        }

        return t;
    }

/*
    WHERE ( GRANTEE IN ( 'PUBLIC', CURRENT_USER )
    OR GRANTEE IN ( SELECT ROLE_NAME FROM ENABLED_ROLES )
    OR GRANTOR = CURRENT_USER
    OR GRANTOR IN ( SELECT ROLE_NAME FROM ENABLED_ROLES ) )

*/

/**
     * The TABLE_PRIVILEGES view has one row for each visible access
     * right for each accessible table definied within this database. <p>
     *
     * Each row is a table privilege description with the following columns: <p>
     *
     * <pre class="SqlCodeExample">
     * GRANTOR      VARCHAR   grantor of access
     * GRANTEE      VARCHAR   grantee of access
     * TABLE_CATALOG    VARCHAR   table catalog
     * TABLE_SCHEMA  VARCHAR   table schema
     * TABLE_NAME   VARCHAR   table name
     * PRIVILEGE_TYPE    VARCHAR   { "SELECT" | "INSERT" | "UPDATE" | "DELETE" | "REFERENCES" | "TRIGGER" }
     * IS_GRANTABLE VARCHAR   { "YES" | "NO" }
     * WITH_HIERARCHY   { "YES" | "NO" }
     * </pre>
     *
     * @return a <code>Table</code> object describing the visible
     *        access rights for each accessible table
     *        defined within this database
     */
    final Table TABLE_PRIVILEGES(Session session, PersistentStore store) {

        Table t = sysTables[TABLE_PRIVILEGES];

        if (t == null) {
            t = createBlankTable(sysTableHsqlNames[TABLE_PRIVILEGES]);

            addColumn(t, "GRANTOR", SQL_IDENTIFIER);           // not null
            addColumn(t, "GRANTEE", SQL_IDENTIFIER);           // not null
            addColumn(t, "TABLE_CATALOG", SQL_IDENTIFIER);
            addColumn(t, "TABLE_SCHEMA", SQL_IDENTIFIER);
            addColumn(t, "TABLE_NAME", SQL_IDENTIFIER);        // not null
            addColumn(t, "PRIVILEGE_TYPE", CHARACTER_DATA);    // not null
            addColumn(t, "IS_GRANTABLE", YES_OR_NO);           // not null
            addColumn(t, "WITH_HIERARCHY", YES_OR_NO);

            //
            HsqlName name = HsqlNameManager.newInfoSchemaObjectName(
                sysTableHsqlNames[SEQUENCES].name, false, SchemaObject.INDEX);

            t.createPrimaryKeyConstraint(name, new int[] {
                0, 1, 2, 3, 4, 5, 6
            }, false);

            return t;
        }

        // calculated column values
        String  tableCatalog;
        String  tableSchema;
        String  tableName;
        Grantee granteeObject;
        String  privilege;

        // intermediate holders
        Iterator tables;
        Table    table;
        Object[] row;

        // column number mappings
        final int grantor        = 0;
        final int grantee        = 1;
        final int table_catalog  = 2;
        final int table_schema   = 3;
        final int table_name     = 4;
        final int privilege_type = 5;
        final int is_grantable   = 6;
        final int with_hierarchy = 7;
        OrderedHashSet grantees =
            session.getGrantee().getGranteeAndAllRolesWithPublic();

        tables = allTables();

        while (tables.hasNext()) {
            table        = (Table) tables.next();
            tableName    = table.getName().name;
            tableCatalog = table.getCatalogName().name;
            tableSchema  = table.getSchemaName().name;

            for (int i = 0; i < grantees.size(); i++) {
                granteeObject = (Grantee) grantees.get(i);

                OrderedHashSet rights =
                    granteeObject.getAllDirectPrivileges(table);
                OrderedHashSet grants =
                    granteeObject.getAllGrantedPrivileges(table);

                if (!grants.isEmpty()) {
                    grants.addAll(rights);

                    rights = grants;
                }

                for (int j = 0; j < rights.size(); j++) {
                    Right right          = (Right) rights.get(j);
                    Right grantableRight = right.getGrantableRights();

                    for (int k = 0; k < Right.privilegeTypes.length; k++) {
                        if (!right.canAccessFully(Right.privilegeTypes[k])) {
                            continue;
                        }

                        privilege           = Right.privilegeNames[k];
                        row                 = t.getEmptyRowData();
                        row[grantor] = right.getGrantor().getName().name;
                        row[grantee] = right.getGrantee().getName().name;
                        row[table_catalog]  = tableCatalog;
                        row[table_schema]   = tableSchema;
                        row[table_name]     = tableName;
                        row[privilege_type] = privilege;
                        row[is_grantable] =
                            right.getGrantee() == table.getOwner()
                            || grantableRight.canAccessFully(
                                Right.privilegeTypes[k]) ? "YES"
                                                         : "NO";
                        row[with_hierarchy] = "NO";

                        try {
                            t.insertSys(session, store, row);
                        } catch (HsqlException e) {}
                    }
                }
            }
        }

        return t;
    }

    Table TABLES(Session session, PersistentStore store) {

        Table t = sysTables[TABLES];

        if (t == null) {
            t = createBlankTable(sysTableHsqlNames[TABLES]);

            addColumn(t, "TABLE_CATALOG", SQL_IDENTIFIER);
            addColumn(t, "TABLE_SCHEMA", SQL_IDENTIFIER);
            addColumn(t, "TABLE_NAME", SQL_IDENTIFIER);
            addColumn(t, "TABLE_TYPE", CHARACTER_DATA);
            addColumn(t, "SELF_REFERENCING_COLUMN_NAME", SQL_IDENTIFIER);
            addColumn(t, "REFERENCE_GENERATION", CHARACTER_DATA);
            addColumn(t, "USER_DEFINED_TYPE_CATALOG", SQL_IDENTIFIER);
            addColumn(t, "USER_DEFINED_TYPE_SCHEMA", SQL_IDENTIFIER);
            addColumn(t, "USER_DEFINED_TYPE_NAME", SQL_IDENTIFIER);
            addColumn(t, "IS_INSERTABLE_INTO", YES_OR_NO);
            addColumn(t, "IS_TYPED", YES_OR_NO);
            addColumn(t, "COMMIT_ACTION", CHARACTER_DATA);

            //
            HsqlName name = HsqlNameManager.newInfoSchemaObjectName(
                sysTableHsqlNames[TABLES].name, false, SchemaObject.INDEX);

            t.createPrimaryKeyConstraint(name, new int[] {
                0, 1, 2,
            }, false);

            return t;
        }

        // intermediate holders
        Iterator  tables;
        Table     table;
        Object[]  row;
        final int table_catalog                = 0;
        final int table_schema                 = 1;
        final int table_name                   = 2;
        final int table_type                   = 3;
        final int self_referencing_column_name = 4;
        final int reference_generation         = 5;
        final int user_defined_type_catalog    = 6;
        final int user_defined_type_schema     = 7;
        final int user_defined_type_name       = 8;
        final int is_insertable_into           = 9;
        final int is_typed                     = 10;
        final int commit_action                = 11;

        // Initialization
        tables = allTables();

        // Do it.
        while (tables.hasNext()) {
            table = (Table) tables.next();

            if (!isAccessibleTable(session, table)) {
                continue;
            }

            row                = t.getEmptyRowData();
            row[table_catalog] = database.getCatalogName().name;
            row[table_schema]  = table.getSchemaName().name;
            row[table_name]    = table.getName().name;

            switch (table.getTableType()) {

                case TableBase.INFO_SCHEMA_TABLE :
                case TableBase.VIEW_TABLE :
                    row[table_type] = "VIEW";
                    row[is_insertable_into] = table.isInsertable()
                                              ? Tokens.T_YES
                                              : Tokens.T_NO;
                    break;

                case TableBase.TEMP_TABLE :
                case TableBase.TEMP_TEXT_TABLE :
                    row[table_type]         = "GLOBAL TEMPORARY";
                    row[is_insertable_into] = "YES";
                    break;

                default :
                    row[table_type] = "BASE TABLE";
                    row[is_insertable_into] = table.isInsertable()
                                              ? Tokens.T_YES
                                              : Tokens.T_NO;
                    break;
            }

            row[self_referencing_column_name] = null;
            row[reference_generation]         = null;
            row[user_defined_type_catalog]    = null;
            row[user_defined_type_schema]     = null;
            row[user_defined_type_name]       = null;
            row[is_typed]                     = "NO";
            row[commit_action] = table.isTemp()
                                 ? (table.onCommitPreserve() ? "PRESERVE"
                                                             : "DELETE")
                                 : null;

            t.insertSys(session, store, row);
        }

        return t;
    }

// -----------------------------------------------------------------------------
// SQL SCHEMATA BASE TABLE

    /**
     * Retrieves a <code>Table</code> object naming the accessible catalogs
     * defined within this database. <p>
     *
     * Each row is a catalog name description with the following column: <p>
     *
     * <pre class="SqlCodeExample">
     * TABLE_CAT   VARCHAR   catalog name
     * </pre> <p>
     *
     * @return a <code>Table</code> object naming the accessible
     *        catalogs defined within this database
     */
    final Table INFORMATION_SCHEMA_CATALOG_NAME(Session session,
            PersistentStore store) {

        Table t = sysTables[INFORMATION_SCHEMA_CATALOG_NAME];

        if (t == null) {
            t = createBlankTable(
                sysTableHsqlNames[INFORMATION_SCHEMA_CATALOG_NAME]);

            addColumn(t, "CATALOG_NAME", SQL_IDENTIFIER);    // not null

            // order:  TABLE_CAT
            // true PK
            HsqlName name = HsqlNameManager.newInfoSchemaObjectName(
                sysTableHsqlNames[INFORMATION_SCHEMA_CATALOG_NAME].name,
                false, SchemaObject.INDEX);

            t.createPrimaryKeyConstraint(name, new int[]{ 0 }, true);

            return t;
        }

        Object[] row = t.getEmptyRowData();

        row[0] = database.getCatalogName().name;

        t.insertSys(session, store, row);

        return t;
    }
}

public void doUpdates(MetricsContext caller) {
  synchronized (this) {
    this.lastUpdate = System.currentTimeMillis();

    // has the extended period for long-living stats elapsed?
    if (this.extendedPeriod > 0 &&
        this.lastUpdate - this.lastExtUpdate >= this.extendedPeriod) {
      this.lastExtUpdate = this.lastUpdate;
      this.compactionTime.resetMinMaxAvg();
      this.compactionSize.resetMinMaxAvg();
      this.flushTime.resetMinMaxAvg();
      this.flushSize.resetMinMaxAvg();
      this.resetAllMinMax();
    }

    this.stores.pushMetric(this.metricsRecord);
    this.storefiles.pushMetric(this.metricsRecord);
    this.storefileIndexSizeMB.pushMetric(this.metricsRecord);
    this.rootIndexSizeKB.pushMetric(this.metricsRecord);
    this.totalStaticIndexSizeKB.pushMetric(this.metricsRecord);
    this.totalStaticBloomSizeKB.pushMetric(this.metricsRecord);
    this.memstoreSizeMB.pushMetric(this.metricsRecord);
    this.regions.pushMetric(this.metricsRecord);
    this.requests.pushMetric(this.metricsRecord);
    this.compactionQueueSize.pushMetric(this.metricsRecord);
    this.blockCacheSize.pushMetric(this.metricsRecord);
    this.blockCacheFree.pushMetric(this.metricsRecord);
    this.blockCacheCount.pushMetric(this.metricsRecord);
    this.blockCacheHitCount.pushMetric(this.metricsRecord);
    this.blockCacheMissCount.pushMetric(this.metricsRecord);
    this.blockCacheEvictedCount.pushMetric(this.metricsRecord);
    this.blockCacheEvictedSingleCount.pushMetric(this.metricsRecord);
    this.blockCacheEvictedMultiCount.pushMetric(this.metricsRecord);
    this.blockCacheEvictedMemoryCount.pushMetric(this.metricsRecord);
    this.blockCacheHitRatio.pushMetric(this.metricsRecord);

    // Be careful. Here is code for MTVR from up in hadoop:
    // public synchronized void inc(final int numOps, final long time) {
    //   currentData.numOperations += numOps;
    //   currentData.time += time;
    //   long timePerOps = time/numOps;
    //    minMax.update(timePerOps);
    // }
    // Means you can't pass a numOps of zero or get a ArithmeticException / by zero.
    // HLog metrics
    addHLogMetric(HLog.getWriteTime(), this.fsWriteLatency);
    addHLogMetric(HLog.getWriteSize(), this.fsWriteSize);
    addHLogMetric(HLog.getSyncTime(), this.fsSyncLatency);
    addHLogMetric(HLog.getGSyncTime(), this.fsGroupSyncLatency);
    // HFile metrics
    int ops = HFile.getReadOps();
    if (ops != 0) this.fsReadLatency.inc(ops, HFile.getReadTime());
    /* NOTE: removed HFile write latency.  2 reasons:
     * 1) Mixing HLog latencies are far higher priority since they're
     *      on-demand and HFile is used in background (compact/flush)
     * 2) HFile metrics are being handled at a higher level
     *      by compaction & flush metrics.
     */

    int writeOps = (int)HRegion.getWriteOps();
    if (writeOps != 0) {
      this.memstoreInsertTime.inc(writeOps, HRegion.getMemstoreInsertTime());
      this.rwccWaitTime.inc(writeOps, HRegion.getRWCCWaitTime());
      this.rowLockTime.inc(writeOps, HRegion.getRowLockTime());
    }

    // push the result
    this.fsReadLatency.pushMetric(this.metricsRecord);
    this.fsWriteLatency.pushMetric(this.metricsRecord);
    this.fsWriteSize.pushMetric(this.metricsRecord);
    this.fsSyncLatency.pushMetric(this.metricsRecord);
    this.fsGroupSyncLatency.pushMetric(this.metricsRecord);
    this.memstoreInsertTime.pushMetric(this.metricsRecord);
    this.rowLockTime.pushMetric(this.metricsRecord);
    this.rwccWaitTime.pushMetric(this.metricsRecord);
    this.compactionTime.pushMetric(this.metricsRecord);
    this.compactionSize.pushMetric(this.metricsRecord);
    this.flushTime.pushMetric(this.metricsRecord);
    this.flushSize.pushMetric(this.metricsRecord);
  }
  this.metricsRecord.update();
}

protected String buildRowSpec(final byte[] row, final Map familyMap, 
    final long startTime, final long endTime, final int maxVersions) {
  StringBuffer sb = new StringBuffer();
  sb.append('/');
  if (accessToken != null) {
    sb.append(accessToken);
    sb.append('/');
  }
  sb.append(Bytes.toStringBinary(name));
  sb.append('/');
  sb.append(Bytes.toStringBinary(row));
  Set families = familyMap.entrySet();
  if (families != null) {
    Iterator i = familyMap.entrySet().iterator();
    if (i.hasNext()) {
      sb.append('/');
    }
    while (i.hasNext()) {
      Map.Entry e = (Map.Entry)i.next();
      Collection quals = (Collection)e.getValue();
      if (quals != null && !quals.isEmpty()) {
        Iterator ii = quals.iterator();
        while (ii.hasNext()) {
          sb.append(Bytes.toStringBinary((byte[])e.getKey()));
          sb.append(':');
          Object o = ii.next();
          // Puts use byte[] but Deletes use KeyValue
          if (o instanceof byte[]) {
            sb.append(Bytes.toStringBinary((byte[])o));
          } else if (o instanceof KeyValue) {
            sb.append(Bytes.toStringBinary(((KeyValue)o).getQualifier()));
          } else {
            throw new RuntimeException("object type not handled");
          }
          if (ii.hasNext()) {
            sb.append(',');
          }
        }
      } else {
        sb.append(Bytes.toStringBinary((byte[])e.getKey()));
        sb.append(':');
      }
      if (i.hasNext()) {
        sb.append(',');
      }
    }
  }
  if (startTime != 0 && endTime != Long.MAX_VALUE) {
    sb.append('/');
    sb.append(startTime);
    if (startTime != endTime) {
      sb.append(',');
      sb.append(endTime);
    }
  } else if (endTime != Long.MAX_VALUE) {
    sb.append('/');
    sb.append(endTime);
  }
  if (maxVersions > 1) {
    sb.append("?v=");
    sb.append(maxVersions);
  }
  return sb.toString();
}

  public long updateColumnValue(byte[] row,
                                byte[] family,
                                byte[] qualifier,
                                long newValue,
                                long now) {
   this.lock.readLock().lock();
    try {
      // create a new KeyValue with 'now' and a 0 memstoreTS == immediately visible
      KeyValue newKv = new KeyValue(row, family, qualifier,
          now,
          Bytes.toBytes(newValue));

      long addedSize = add(newKv);

      // now find and RM the old one(s) to prevent version explosion:
	  KeyValue firstKv = KeyValue.createFirstOnRow(
			  newKv.getBuffer(), newKv.getRowOffset(), newKv.getRowLength(),
			  newKv.getBuffer(), newKv.getFamilyOffset(), newKv.getFamilyLength(),
			  newKv.getBuffer(), newKv.getQualifierOffset(), newKv.getQualifierLength());
      SortedSet<KeyValue> ss = kvset.tailSet(firstKv);
      Iterator<KeyValue> it = ss.iterator();
      while ( it.hasNext() ) {
        KeyValue kv = it.next();

        if (kv == newKv) {
          // ignore the one i just put in (heh)
          continue;
        }
        // if this isnt the row we are interested in, then bail:
        if (0 != Bytes.compareTo(
            newKv.getBuffer(), newKv.getRowOffset(), newKv.getRowLength(),
            kv.getBuffer(), kv.getRowOffset(), kv.getRowLength())) {
          break; // rows dont match, bail.
        }

        // if the qualifier matches and it's a put, just RM it out of the kvset.
        if (0 == Bytes.compareTo(
            newKv.getBuffer(), newKv.getQualifierOffset(), newKv.getQualifierLength(),
            kv.getBuffer(), kv.getQualifierOffset(), kv.getQualifierLength())) {

          if (kv.getType() == KeyValue.Type.Put.getCode()) {
            // false means there was a change, so give us the size.
            addedSize -= heapSizeChange(kv, true);

            it.remove();
          }
        }
      }

      return addedSize;
    } finally {
      this.lock.readLock().unlock();
    }
  }

CompactSelection compactSelection(List<StoreFile> candidates)
    throws IOException {
  // ASSUMPTION!!! filesCompacting is locked when calling this function

  /* normal skew:
   *
   *         older ----> newer
   *     _
   *    | |   _
   *    | |  | |   _
   *  --|-|- |-|- |-|---_-------_-------  minCompactSize
   *    | |  | |  | |  | |  _  | |
   *    | |  | |  | |  | | | | | |
   *    | |  | |  | |  | | | | | |
   */
  CompactSelection compactSelection = new CompactSelection(conf, candidates);

  boolean forcemajor = this.forceMajor && filesCompacting.isEmpty();
  if (!forcemajor) {
    // do not compact old files above a configurable threshold
    // save all references. we MUST compact them
    int pos = 0;
    while (pos < compactSelection.getFilesToCompact().size() &&
           compactSelection.getFilesToCompact().get(pos).getReader().length()
             > maxCompactSize &&
           !compactSelection.getFilesToCompact().get(pos).isReference()) ++pos;
    compactSelection.clearSubList(0, pos);
  }

  if (compactSelection.getFilesToCompact().isEmpty()) {
    LOG.debug(this.storeNameStr + ": no store files to compact");
    compactSelection.emptyFileList();
    return compactSelection;
  }

  // major compact on user action or age (caveat: we have too many files)
  boolean majorcompaction =
    (forcemajor || isMajorCompaction(compactSelection.getFilesToCompact()))
    && compactSelection.getFilesToCompact().size() < this.maxFilesToCompact;

  if (!majorcompaction &&
      !hasReferences(compactSelection.getFilesToCompact())) {
    // we're doing a minor compaction, let's see what files are applicable
    int start = 0;
    double r = compactSelection.getCompactSelectionRatio();

    // exclude bulk import files from minor compactions, if configured
    if (conf.getBoolean("hbase.hstore.compaction.exclude.bulk", false)) {
      compactSelection.getFilesToCompact().removeAll(Collections2.filter(
          compactSelection.getFilesToCompact(),
          new Predicate<StoreFile>() {
            @Override
            public boolean apply(StoreFile input) {
              return input.isBulkLoadResult();
            }
          }));
    }

    // skip selection algorithm if we don't have enough files
    if (compactSelection.getFilesToCompact().size() < this.minFilesToCompact) {
      compactSelection.emptyFileList();
      return compactSelection;
    }

    /* TODO: add sorting + unit test back in when HBASE-2856 is fixed
    //sort files by size to correct when normal skew is altered by bulk load
    Collections.sort(filesToCompact, StoreFile.Comparators.FILE_SIZE);
     */

    // get store file sizes for incremental compacting selection.
    int countOfFiles = compactSelection.getFilesToCompact().size();
    long [] fileSizes = new long[countOfFiles];
    long [] sumSize = new long[countOfFiles];
    for (int i = countOfFiles-1; i >= 0; --i) {
      StoreFile file = compactSelection.getFilesToCompact().get(i);
      fileSizes[i] = file.getReader().length();
      // calculate the sum of fileSizes[i,i+maxFilesToCompact-1) for algo
      int tooFar = i + this.maxFilesToCompact - 1;
      sumSize[i] = fileSizes[i]
                 + ((i+1    < countOfFiles) ? sumSize[i+1]      : 0)
                 - ((tooFar < countOfFiles) ? fileSizes[tooFar] : 0);
    }

    /* Start at the oldest file and stop when you find the first file that
     * meets compaction criteria:
     *   (1) a recently-flushed, small file (i.e. <= minCompactSize)
     *      OR
     *   (2) within the compactRatio of sum(newer_files)
     * Given normal skew, any newer files will also meet this criteria
     *
     * Additional Note:
     * If fileSizes.size() >> maxFilesToCompact, we will recurse on
     * compact().  Consider the oldest files first to avoid a
     * situation where we always compact [end-threshold,end).  Then, the
     * last file becomes an aggregate of the previous compactions.
     */
    while(countOfFiles - start >= this.minFilesToCompact &&
          fileSizes[start] >
            Math.max(minCompactSize, (long)(sumSize[start+1] * r))) {
      ++start;
    }
    int end = Math.min(countOfFiles, start + this.maxFilesToCompact);
    long totalSize = fileSizes[start]
                   + ((start+1 < countOfFiles) ? sumSize[start+1] : 0);
    compactSelection = compactSelection.getSubList(start, end);

    // if we don't have enough files to compact, just wait
    if (compactSelection.getFilesToCompact().size() < this.minFilesToCompact) {
      if (LOG.isDebugEnabled()) {
        LOG.debug("Skipped compaction of " + this.storeNameStr
          + ".  Only " + (end - start) + " file(s) of size "
          + StringUtils.humanReadableInt(totalSize)
          + " have met compaction criteria.");
      }
      compactSelection.emptyFileList();
      return compactSelection;
    }
  } else {
    // all files included in this compaction, up to max
    if (compactSelection.getFilesToCompact().size() > this.maxFilesToCompact) {
      int pastMax =
        compactSelection.getFilesToCompact().size() - this.maxFilesToCompact;
      compactSelection.clearSubList(0, pastMax);
    }
  }
  return compactSelection;
}

public synchronized void replicateEntries(HLog.Entry[] entries)
    throws IOException {
  // Very simple optimization where we batch sequences of rows going
  // to the same table.
  try {
    long totalReplicated = 0;
    byte[] lastTable = HConstants.EMPTY_BYTE_ARRAY;
    List<Put> puts = new ArrayList<Put>();
    for (HLog.Entry entry : entries) {
      WALEdit edit = entry.getEdit();
      List<KeyValue> kvs = edit.getKeyValues();
      if (kvs.get(0).isDelete()) {
        Delete delete = new Delete(kvs.get(0).getRow(),
            kvs.get(0).getTimestamp(), null);
        for (KeyValue kv : kvs) {
          if (kv.isDeleteFamily()) {
            delete.deleteFamily(kv.getFamily());
          } else if (!kv.isEmptyColumn()) {
            delete.deleteColumn(kv.getFamily(),
                kv.getQualifier());
          }
        }
        delete(entry.getKey().getTablename(), delete);
      } else {
        // Switching table, flush
        if (!Bytes.equals(lastTable, entry.getKey().getTablename())) {
          put(lastTable, puts);
        }
        // With mini-batching, we need to expect multiple rows per edit
        byte[] lastKey = kvs.get(0).getRow();
        Put put = new Put(kvs.get(0).getRow(),
            kvs.get(0).getTimestamp());
        for (KeyValue kv : kvs) {
          if (!Bytes.equals(lastKey, kv.getRow())) {
            puts.add(put);
            put = new Put(kv.getRow(), kv.getTimestamp());
          }
          put.add(kv.getFamily(), kv.getQualifier(), kv.getValue());
          lastKey = kv.getRow();
        }
        puts.add(put);
        lastTable = entry.getKey().getTablename();
      }
      totalReplicated++;
    }
    put(lastTable, puts);
    LOG.info("Total replicated: " + totalReplicated);
  } catch (IOException ex) {
    if (ex.getCause() instanceof TableNotFoundException) {
      LOG.warn("Losing edits because: ", ex);
    } else {
      // Should we log rejected edits in a file for replay?
      LOG.error("Unable to accept edit because", ex);
      this.stop.set(true);
      throw ex;
    }
  } catch (RuntimeException re) {
    if (re.getCause() instanceof TableNotFoundException) {
      LOG.warn("Losing edits because: ", re);
    } else {
      this.stop.set(true);
      throw re;
    }
  }
}

