protected String buildRowSpec(final byte[] row, final Map familyMap, 
    final long startTime, final long endTime, final int maxVersions) {
  StringBuffer sb = new StringBuffer();
  sb.append('/');
  if (accessToken != null) {
    sb.append(accessToken);
    sb.append('/');
  }
  sb.append(Bytes.toStringBinary(name));
  sb.append('/');
  sb.append(Bytes.toStringBinary(row));
  Set families = familyMap.entrySet();
  if (families != null) {
    Iterator i = familyMap.entrySet().iterator();
    if (i.hasNext()) {
      sb.append('/');
    }
    while (i.hasNext()) {
      Map.Entry e = (Map.Entry)i.next();
      Collection quals = (Collection)e.getValue();
      if (quals != null && !quals.isEmpty()) {
        Iterator ii = quals.iterator();
        while (ii.hasNext()) {
          sb.append(Bytes.toStringBinary((byte[])e.getKey()));
          sb.append(':');
          Object o = ii.next();
          // Puts use byte[] but Deletes use KeyValue
          if (o instanceof byte[]) {
            sb.append(Bytes.toStringBinary((byte[])o));
          } else if (o instanceof KeyValue) {
            sb.append(Bytes.toStringBinary(((KeyValue)o).getQualifier()));
          } else {
            throw new RuntimeException("object type not handled");
          }
          if (ii.hasNext()) {
            sb.append(',');
          }
        }
      } else {
        sb.append(Bytes.toStringBinary((byte[])e.getKey()));
        sb.append(':');
      }
      if (i.hasNext()) {
        sb.append(',');
      }
    }
  }
  if (startTime != 0 && endTime != Long.MAX_VALUE) {
    sb.append('/');
    sb.append(startTime);
    if (startTime != endTime) {
      sb.append(',');
      sb.append(endTime);
    }
  } else if (endTime != Long.MAX_VALUE) {
    sb.append('/');
    sb.append(endTime);
  }
  if (maxVersions > 1) {
    sb.append("?v=");
    sb.append(maxVersions);
  }
  return sb.toString();
}

public static String dump(ZooKeeperWatcher zkw) {
  StringBuilder sb = new StringBuilder();
  try {
    sb.append("HBase is rooted at ").append(zkw.baseZNode);
    sb.append("\nActive master address: ").append(
        ServerName.parseVersionedServerName(getData(zkw, zkw.masterAddressZNode)));
    sb.append("\nBackup master addresses:");
    for (String child : listChildrenNoWatch(zkw,
                                            zkw.backupMasterAddressesZNode)) {
      sb.append("\n ").append(child);
    }
    sb.append("\nRegion server holding ROOT: ").append(
        Bytes.toStringBinary(getData(zkw, zkw.rootServerZNode)));
    sb.append("\nRegion servers:");
    for (String child : listChildrenNoWatch(zkw, zkw.rsZNode)) {
      sb.append("\n ").append(child);
    }
    sb.append("\nQuorum Server Statistics:");
    String[] servers = zkw.getQuorum().split(",");
    for (String server : servers) {
      sb.append("\n ").append(server);
      try {
        String[] stat = getServerStats(server, ZKUtil.zkDumpConnectionTimeOut);

        if (stat == null) {
          sb.append("[Error] invalid quorum server: " + server);
          break;
        }

        for (String s : stat) {
          sb.append("\n  ").append(s);
        }
      } catch (Exception e) {
        sb.append("\n  ERROR: ").append(e.getMessage());
      }
    }
  } catch (KeeperException ke) {
    sb.append("\nFATAL ZooKeeper Exception!\n");
    sb.append("\n" + ke.getMessage());
  }
  return sb.toString();
}

protected void metrics() {
  this.metrics.regions.set(this.onlineRegions.size());
  this.metrics.incrementRequests(this.requestCount.get());
  this.metrics.requests.intervalHeartBeat();
  // Is this too expensive every three seconds getting a lock on onlineRegions
  // and then per store carried? Can I make metrics be sloppier and avoid
  // the synchronizations?
  int stores = 0;
  int storefiles = 0;
  long memstoreSize = 0;
  int readRequestsCount = 0;
  int writeRequestsCount = 0;
  long storefileIndexSize = 0;
  HDFSBlocksDistribution hdfsBlocksDistribution =
    new HDFSBlocksDistribution();
  long totalStaticIndexSize = 0;
  long totalStaticBloomSize = 0;
  for (Map.Entry<String, HRegion> e : this.onlineRegions.entrySet()) {
      HRegion r = e.getValue();
      memstoreSize += r.memstoreSize.get();
      readRequestsCount += r.readRequestsCount.get();
      writeRequestsCount += r.writeRequestsCount.get();
      synchronized (r.stores) {
        stores += r.stores.size();
        for (Map.Entry<byte[], Store> ee : r.stores.entrySet()) {
          Store store = ee.getValue();
          storefiles += store.getStorefilesCount();
          storefileIndexSize += store.getStorefilesIndexSize();
          totalStaticIndexSize += store.getTotalStaticIndexSize();
          totalStaticBloomSize += store.getTotalStaticBloomSize();
        }
      }

      hdfsBlocksDistribution.add(r.getHDFSBlocksDistribution());
    }
  this.metrics.stores.set(stores);
  this.metrics.storefiles.set(storefiles);
  this.metrics.memstoreSizeMB.set((int) (memstoreSize / (1024 * 1024)));
  this.metrics.storefileIndexSizeMB.set(
      (int) (storefileIndexSize / (1024 * 1024)));
  this.metrics.rootIndexSizeKB.set(
      (int) (storefileIndexSize / 1024));
  this.metrics.totalStaticIndexSizeKB.set(
      (int) (totalStaticIndexSize / 1024));
  this.metrics.totalStaticBloomSizeKB.set(
      (int) (totalStaticBloomSize / 1024));
  this.metrics.readRequestsCount.set(readRequestsCount);
  this.metrics.writeRequestsCount.set(writeRequestsCount);
  this.metrics.compactionQueueSize.set(compactSplitThread
      .getCompactionQueueSize());
  this.metrics.flushQueueSize.set(cacheFlusher
      .getFlushQueueSize());

  BlockCache blockCache = cacheConfig.getBlockCache();
  if (blockCache != null) {
    this.metrics.blockCacheCount.set(blockCache.size());
    this.metrics.blockCacheFree.set(blockCache.getFreeSize());
    this.metrics.blockCacheSize.set(blockCache.getCurrentSize());
    CacheStats cacheStats = blockCache.getStats();
    this.metrics.blockCacheHitCount.set(cacheStats.getHitCount());
    this.metrics.blockCacheMissCount.set(cacheStats.getMissCount());
    this.metrics.blockCacheEvictedCount.set(blockCache.getEvictedCount());
    double ratio = blockCache.getStats().getHitRatio();
    int percent = (int) (ratio * 100);
    this.metrics.blockCacheHitRatio.set(percent);
    ratio = blockCache.getStats().getHitCachingRatio();
    percent = (int) (ratio * 100);
    this.metrics.blockCacheHitCachingRatio.set(percent);
  }
  float localityIndex = hdfsBlocksDistribution.getBlockLocalityIndex(
    getServerName().getHostname());
  int percent = (int) (localityIndex * 100);
  this.metrics.hdfsBlocksLocalityIndex.set(percent);

}

