public void doUpdates(MetricsContext caller) {
  synchronized (this) {
    this.lastUpdate = System.currentTimeMillis();

    // has the extended period for long-living stats elapsed?
    if (this.extendedPeriod > 0 &&
        this.lastUpdate - this.lastExtUpdate >= this.extendedPeriod) {
      this.lastExtUpdate = this.lastUpdate;
      this.compactionTime.resetMinMaxAvg();
      this.compactionSize.resetMinMaxAvg();
      this.flushTime.resetMinMaxAvg();
      this.flushSize.resetMinMaxAvg();
      this.resetAllMinMax();
    }

    this.stores.pushMetric(this.metricsRecord);
    this.storefiles.pushMetric(this.metricsRecord);
    this.hlogFileCount.pushMetric(this.metricsRecord);
    this.hlogFileSizeMB.pushMetric(this.metricsRecord);
    this.storefileIndexSizeMB.pushMetric(this.metricsRecord);
    this.rootIndexSizeKB.pushMetric(this.metricsRecord);
    this.totalStaticIndexSizeKB.pushMetric(this.metricsRecord);
    this.totalStaticBloomSizeKB.pushMetric(this.metricsRecord);
    this.memstoreSizeMB.pushMetric(this.metricsRecord);
    this.mbInMemoryWithoutWAL.pushMetric(this.metricsRecord);
    this.numPutsWithoutWAL.pushMetric(this.metricsRecord);
    this.readRequestsCount.pushMetric(this.metricsRecord);
    this.writeRequestsCount.pushMetric(this.metricsRecord);
    this.regions.pushMetric(this.metricsRecord);
    this.requests.pushMetric(this.metricsRecord);
    this.compactionQueueSize.pushMetric(this.metricsRecord);
    this.flushQueueSize.pushMetric(this.metricsRecord);
    this.blockCacheSize.pushMetric(this.metricsRecord);
    this.blockCacheFree.pushMetric(this.metricsRecord);
    this.blockCacheCount.pushMetric(this.metricsRecord);
    this.blockCacheHitCount.pushMetric(this.metricsRecord);
    this.blockCacheMissCount.pushMetric(this.metricsRecord);
    this.blockCacheEvictedCount.pushMetric(this.metricsRecord);
    this.blockCacheHitRatio.pushMetric(this.metricsRecord);
    this.blockCacheHitCachingRatio.pushMetric(this.metricsRecord);
    this.hdfsBlocksLocalityIndex.pushMetric(this.metricsRecord);
    this.blockCacheHitRatioPastNPeriods.pushMetric(this.metricsRecord);
    this.blockCacheHitCachingRatioPastNPeriods.pushMetric(this.metricsRecord);

    // Mix in HFile and HLog metrics
    // Be careful. Here is code for MTVR from up in hadoop:
    // public synchronized void inc(final int numOps, final long time) {
    //   currentData.numOperations += numOps;
    //   currentData.time += time;
    //   long timePerOps = time/numOps;
    //    minMax.update(timePerOps);
    // }
    // Means you can't pass a numOps of zero or get a ArithmeticException / by zero.
    // HLog metrics
    addHLogMetric(HLog.getWriteTime(), this.fsWriteLatency);
    addHLogMetric(HLog.getWriteSize(), this.fsWriteSize);
    addHLogMetric(HLog.getSyncTime(), this.fsSyncLatency);
    addHLogMetric(HLog.getSlowAppendTime(), this.slowHLogAppendTime);
    this.slowHLogAppendCount.set(HLog.getSlowAppendCount());
    // HFile metrics, sequential reads
    int ops = HFile.getReadOps(); 
    if (ops != 0) this.fsReadLatency.inc(ops, HFile.getReadTimeMs());
    // HFile metrics, positional reads
    ops = HFile.getPreadOps(); 
    if (ops != 0) this.fsPreadLatency.inc(ops, HFile.getPreadTimeMs());
    this.checksumFailuresCount.set(HFile.getChecksumFailuresCount());

    /* NOTE: removed HFile write latency.  2 reasons:
     * 1) Mixing HLog latencies are far higher priority since they're 
     *      on-demand and HFile is used in background (compact/flush)
     * 2) HFile metrics are being handled at a higher level 
     *      by compaction & flush metrics.
     */

    for(Long latency : HFile.getReadLatenciesNanos()) {
      this.fsReadLatencyHistogram.update(latency);
    }
    for(Long latency : HFile.getPreadLatenciesNanos()) {
      this.fsPreadLatencyHistogram.update(latency);
    }
    for(Long latency : HFile.getWriteLatenciesNanos()) {
      this.fsWriteLatencyHistogram.update(latency);
    }


    // push the result
    this.fsPreadLatency.pushMetric(this.metricsRecord);
    this.fsReadLatency.pushMetric(this.metricsRecord);
    this.fsWriteLatency.pushMetric(this.metricsRecord);
    this.fsWriteSize.pushMetric(this.metricsRecord);

    this.fsReadLatencyHistogram.pushMetric(this.metricsRecord);
    this.fsWriteLatencyHistogram.pushMetric(this.metricsRecord);
    this.fsPreadLatencyHistogram.pushMetric(this.metricsRecord);

    this.fsSyncLatency.pushMetric(this.metricsRecord);
    this.compactionTime.pushMetric(this.metricsRecord);
    this.compactionSize.pushMetric(this.metricsRecord);
    this.flushTime.pushMetric(this.metricsRecord);
    this.flushSize.pushMetric(this.metricsRecord);
    this.slowHLogAppendCount.pushMetric(this.metricsRecord);
    this.regionSplitSuccessCount.pushMetric(this.metricsRecord);
    this.regionSplitFailureCount.pushMetric(this.metricsRecord);
    this.checksumFailuresCount.pushMetric(this.metricsRecord);
    this.updatesBlockedSeconds.pushMetric(this.metricsRecord);
    this.updatesBlockedSecondsHighWater.pushMetric(this.metricsRecord);
  }
  this.metricsRecord.update();
}

private void handleRegion(final RegionTransitionData data, int expectedVersion) {
  synchronized(regionsInTransition) {
    HRegionInfo hri = null;
    if (data == null || data.getOrigin() == null) {
      LOG.warn("Unexpected NULL input " + data);
      return;
    }
    ServerName sn = data.getOrigin();
    // Check if this is a special HBCK transition
    if (sn.equals(HConstants.HBCK_CODE_SERVERNAME)) {
      handleHBCK(data);
      return;
    }
    String encodedName = HRegionInfo.encodeRegionName(data.getRegionName());
    String prettyPrintedRegionName = HRegionInfo.prettyPrint(encodedName);
    // Verify this is a known server
    if (!serverManager.isServerOnline(sn) &&
        !this.master.getServerName().equals(sn)
        && !ignoreStatesRSOffline.contains(data.getEventType())) {
      LOG.warn("Attempted to handle region transition for server but " +
        "server is not online: " + prettyPrintedRegionName);
      return;
    }
    // Printing if the event was created a long time ago helps debugging
    boolean lateEvent = data.getStamp() <
        (System.currentTimeMillis() - 15000);
    LOG.debug("Handling transition=" + data.getEventType() +
      ", server=" + data.getOrigin() + ", region=" +
        (prettyPrintedRegionName == null? "null": prettyPrintedRegionName)  +
        (lateEvent? ", which is more than 15 seconds late" : ""));
    RegionState regionState = regionsInTransition.get(encodedName);
    switch (data.getEventType()) {
      case M_ZK_REGION_OFFLINE:
        // Nothing to do.
        break;

      case RS_ZK_REGION_SPLITTING:
        if (!isInStateForSplitting(regionState)) break;
        addSplittingToRIT(sn, encodedName);
        break;

      case RS_ZK_REGION_SPLIT:
        // RegionState must be null, or SPLITTING or PENDING_CLOSE.
        if (!isInStateForSplitting(regionState)) break;
        // If null, add SPLITTING state before going to SPLIT
        if (regionState == null) {
          regionState = addSplittingToRIT(sn, encodedName);
          String message = "Received SPLIT for region " + prettyPrintedRegionName +
            " from server " + sn;
          // If still null, it means we cannot find it and it was already processed
          if (regionState == null) {
            LOG.warn(message + " but it doesn't exist anymore," +
                " probably already processed its split");
            break;
          }
          LOG.info(message +
              " but region was not first in SPLITTING state; continuing");
        }
        // Check it has daughters.
        byte [] payload = data.getPayload();
        List<HRegionInfo> daughters = null;
        try {
          daughters = Writables.getHRegionInfos(payload, 0, payload.length);
        } catch (IOException e) {
          LOG.error("Dropped split! Failed reading split payload for " +
            prettyPrintedRegionName);
          break;
        }
        assert daughters.size() == 2;
        // Assert that we can get a serverinfo for this server.
        if (!this.serverManager.isServerOnline(sn)) {
          LOG.error("Dropped split! ServerName=" + sn + " unknown.");
          break;
        }
        // Run handler to do the rest of the SPLIT handling.
        this.executorService.submit(new SplitRegionHandler(master, this,
          regionState.getRegion(), sn, daughters));
        break;

      case M_ZK_REGION_CLOSING:
        hri = checkIfInFailover(regionState, encodedName, data);
        if (hri != null) {
          regionState = new RegionState(hri, RegionState.State.CLOSING, data
             .getStamp(), data.getOrigin());
          regionsInTransition.put(encodedName, regionState);
          failoverProcessedRegions.put(encodedName, hri);
          break;
        }
        // Should see CLOSING after we have asked it to CLOSE or additional
        // times after already being in state of CLOSING
        if (regionState == null ||
            (!regionState.isPendingClose() && !regionState.isClosing())) {
          LOG.warn("Received CLOSING for region " + prettyPrintedRegionName +
            " from server " + data.getOrigin() + " but region was in " +
            " the state " + regionState + " and not " +
            "in expected PENDING_CLOSE or CLOSING states");
          return;
        }
        // Transition to CLOSING (or update stamp if already CLOSING)
        regionState.update(RegionState.State.CLOSING,
            data.getStamp(), data.getOrigin());
        break;

      case RS_ZK_REGION_CLOSED:
        hri = checkIfInFailover(regionState, encodedName, data);
        if (hri != null) {
          regionState = new RegionState(hri, RegionState.State.CLOSED, data
              .getStamp(), data.getOrigin());
          regionsInTransition.put(encodedName, regionState);
          removeClosedRegion(regionState.getRegion());
          new ClosedRegionHandler(master, this, regionState.getRegion())
            .process();
          failoverProcessedRegions.put(encodedName, hri);
          break;
        }
        // Should see CLOSED after CLOSING but possible after PENDING_CLOSE
        if (regionState == null ||
            (!regionState.isPendingClose() && !regionState.isClosing())) {
          LOG.warn("Received CLOSED for region " + prettyPrintedRegionName +
              " from server " + data.getOrigin() + " but region was in " +
              " the state " + regionState + " and not " +
              "in expected PENDING_CLOSE or CLOSING states");
          return;
        }
        // Handle CLOSED by assigning elsewhere or stopping if a disable
        // If we got here all is good.  Need to update RegionState -- else
        // what follows will fail because not in expected state.
        regionState.update(RegionState.State.CLOSED,
            data.getStamp(), data.getOrigin());
        removeClosedRegion(regionState.getRegion());
        this.executorService.submit(new ClosedRegionHandler(master,
          this, regionState.getRegion()));
        break;

      case RS_ZK_REGION_FAILED_OPEN:
        hri = checkIfInFailover(regionState, encodedName, data);
        if (hri != null) {
          regionState = new RegionState(hri, RegionState.State.CLOSED, data
              .getStamp(), data.getOrigin());
          regionsInTransition.put(encodedName, regionState);
          new ClosedRegionHandler(master, this, regionState.getRegion())
            .process();
          failoverProcessedRegions.put(encodedName, hri);
          break;
        }
        if (regionState == null ||
            (!regionState.isOffline() && !regionState.isPendingOpen() && !regionState.isOpening())) {
          LOG.warn("Received FAILED_OPEN for region " + prettyPrintedRegionName +
              " from server " + data.getOrigin() + " but region was in " +
              " the state " + regionState + " and not in OFFLINE, PENDING_OPEN or OPENING");
          return;
        }
        // Handle this the same as if it were opened and then closed.
        regionState.update(RegionState.State.CLOSED,
            data.getStamp(), data.getOrigin());
        // When there are more than one region server a new RS is selected as the 
        // destination and the same is updated in the regionplan. (HBASE-5546)
        getRegionPlan(regionState, sn, true);
        this.executorService.submit(new ClosedRegionHandler(master,
          this, regionState.getRegion()));
        break;

      case RS_ZK_REGION_OPENING:
        hri = checkIfInFailover(regionState, encodedName, data);       
        if (hri != null) {
          regionState = new RegionState(hri, RegionState.State.OPENING, data
              .getStamp(), data.getOrigin());
          regionsInTransition.put(encodedName, regionState);
          failoverProcessedRegions.put(encodedName, hri);
          break;
        }
        if (regionState == null ||
            (!regionState.isOffline() && !regionState.isPendingOpen() &&
                !regionState.isOpening())) {
            LOG.warn("Received OPENING for region " + prettyPrintedRegionName +  " from server " +
              sn + " but region was in " + " the state " + regionState + " and not " +
              "in expected OFFLINE, PENDING_OPEN or OPENING states");
            return;
        }
        // Transition to OPENING (or update stamp if already OPENING)
        regionState.update(RegionState.State.OPENING,
            data.getStamp(), data.getOrigin());
        break;

      case RS_ZK_REGION_OPENED:
        hri = checkIfInFailover(regionState, encodedName, data);
        if (hri != null) {
          regionState = new RegionState(hri, RegionState.State.OPEN, data
              .getStamp(), data.getOrigin());
          regionsInTransition.put(encodedName, regionState);
          new OpenedRegionHandler(master, this, regionState.getRegion(), data
            .getOrigin(), expectedVersion).process();
          failoverProcessedRegions.put(encodedName, hri);
          break;
        }
        // Should see OPENED after OPENING but possible after PENDING_OPEN
        if (regionState == null ||
            (!regionState.isOffline() && !regionState.isPendingOpen() && !regionState.isOpening())) {
          LOG.warn("Received OPENED for region " +
              prettyPrintedRegionName +
              " from server " + data.getOrigin() + " but region was in " +
              " the state " + regionState + " and not " +
              "in expected OFFLINE, PENDING_OPEN or OPENING states");
          return;
        }
        // Handle OPENED by removing from transition and deleted zk node
        regionState.update(RegionState.State.OPEN,
            data.getStamp(), data.getOrigin());
        this.executorService.submit(
          new OpenedRegionHandler(master, this, regionState.getRegion(),
            data.getOrigin(), expectedVersion));
        break;
    }
  }
}

