        if (Model.getFacade().isAObjectFlowState(dm)) {
            return NO_PROBLEM;
        }

	String myName = Model.getFacade().getName(dm);
	if (myName == null || myName.equals("") || myName.length() == 0) {
            return PROBLEM_FOUND;
