private void deleteMetaRegion(HbckInfo hi) throws IOException {
  Delete d = new Delete(hi.metaEntry.getRegionName());
  meta.delete(d);
  meta.flushCommits();
  LOG.info("Deleted " + hi.metaEntry.getRegionNameAsString() + " from META" );
